[CmdletBinding()]
param([string]$BaselinePath=(Join-Path $PSScriptRoot '..\references\authoritative-step-baseline.v1.json'))
$ErrorActionPreference='Stop';$b=Get-Content -Raw -Encoding UTF8 $BaselinePath|ConvertFrom-Json;$root=[IO.Path]::GetFullPath((Get-Location).Path);$missing=@();$resourceHashes=@();foreach($p in $b.requiredResources.PSObject.Properties){foreach($v in @($p.Value.contract,$p.Value.read,$p.Value.index,$p.Value.role)){if($v -and $v -match '\.(json|yaml|md|psm1)$'){$full=[IO.Path]::GetFullPath((Join-Path $root $v));if(-not(Test-Path $full -PathType Leaf)){$missing+=$v}else{$resourceHashes+=[ordered]@{path=$v;sha256=(Get-FileHash $full -Algorithm SHA256).Hash.ToLowerInvariant()}}}}};$ord=@($b.stages|% ordinal);$contiguous=($ord -join ',') -eq ((1..$b.stages.Count)-join ',');$timingOk=($b.invocationTiming.taskFocus.phase -match 'before') -and ($b.invocationTiming.taskContext.phase -match 'after-focus') -and ($b.invocationTiming.taskContext.phase -match 'before-knowledge') -and ($b.invocationTiming.completion.phase -match 'after-evidence');$status=if($missing.Count -eq 0 -and $contiguous -and $timingOk -and $b.skipPolicy.allowSkip -eq $false -and $b.skipPolicy.allowReorder -eq $false){'passed'}else{'blocked'};[ordered]@{status=$status;baselineId=$b.baselineId;stageCount=$b.stages.Count;ordered=$contiguous;timingFrozen=$timingOk;missingResources=$missing;resourceHashes=$resourceHashes;skipPolicy=$b.skipPolicy;nonClaims=$b.nonClaims}|ConvertTo-Json -Depth 8;if($status -ne 'passed'){exit 1}
